import * as THREE from 'three/webgpu';
import { texture, color, uv } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // ---- Background plane ----
  const atlasRect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = atlasRect.w / atlasRect.h;
  const planeWidth = 3.2;
  const planeHeight = planeWidth / aspect;

  const bgTexture = ctx.textureLoader.load(config.imageUrl);
  bgTexture.offset.set(0, 0);
  bgTexture.repeat.set(1, 1);
  bgTexture.needsUpdate = true;

  const bgMat = new THREE.MeshBasicNodeMaterial({
    colorNode: texture(bgTexture),
    side: THREE.DoubleSide,
  });
  const bgGeo = new THREE.PlaneGeometry(planeWidth, planeHeight);
  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -0.01); // slightly behind text
  group.add(bgMesh);

  // ---- Text (body style) ----
  const textOptions = {
    font: 'JetBrains Mono',
    weight: 400,
    size: 0.13,       // body scale from type tokens
    letterSpacing: 0.02,
    align: 'center',
    color: '#e8ecf2', // paper color for readability
    materialType: 'basic',
  };
  const textMesh = ctx.fontAtlas(config.textContent, textOptions);
  textMesh.position.set(0, -0.2, 0); // centered vertically in plane
  group.add(textMesh);

  // ---- Placement ----
  const pos = config.scenePosition || [0, 3, 0];
  const rot = config.sceneRotation || [0, 0, 0];
  const scl = config.sceneScale || [1, 1, 1];
  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(rot[0], rot[1], rot[2]);
  group.scale.set(scl[0], scl[1], scl[2]);

  // ---- Cinematic primitives (none) ----
  // (no primitives in this config)

  // ---- Event Handlers (none) ----
  group.userData.handlers = {};

  // ---- Cleanup ----
  const timeline = gsap.timeline({ paused: true });
  group.userData.cleanup = () => {
    timeline.kill();
    bgGeo.dispose();
    bgMat.dispose();
    bgTexture.dispose();
    // dispose text material & geometry if accessible
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
  };

  return group;
}
